pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // General rule: If the caller is the current owner and calls burn(x) (onlyOwner), the owner stored in the contract remains the same deployer owner afterwards.
    // We fuzz the burn amount and an address that will act as the caller. The property requires the caller to be the current owner; we let the fuzzer choose an address and only proceed when it's the deployer (wide domain: allow any address but require it to match deployer to be admissible).
    function testFuzz_property(uint256 burnAmount, address caller) public {
        // keep domain wide: require caller equals the deployer (the account that deployed c) so the call is admissible for onlyOwner
        address deployer = address(this); // in setUp we deployed c from this test contract
        vm.assume(caller == deployer);

        // ensure deployer has enough balance to burn some amount; set balance directly via minting through onlyOwner (this contract is owner)
        // wide: bound burnAmount to a reasonable range to avoid underflow in the reference when burning more than balance
        uint256 maxBalance = 1e18;
        uint256 amt = bound(burnAmount, 0, maxBalance);

        // mint some tokens to deployer so burn can succeed when amt <= balance
        c.mintToken(deployer, maxBalance);

        // record owner before burn
        address ownerBefore = c.owner();

        // perform burn as the owner (this test contract). Use vm.prank to set msg.sender.
        vm.prank(deployer);
        bool ok;
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference implementation preserves owner (owner stays deployer).
        // We assert that if the burn call succeeded (ok==true) then owner remains the same deployer address.
        // This is a single assertTrue reading c.owner().
        if (ok) {
            assertTrue(c.owner() == ownerBefore);
        } else {
            // if burn reverted (e.g., burning more than balance), the reference also reverts and owner remains unchanged; we still assert owner equals ownerBefore
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

