        // Then we call c.owned() but we need to make the immediate caller be `caller`. Achieve this by using a simple trick:
        // perform a call to c.owned() using `caller` as the target by using address(c).call with encoded function selector and
        // set msg.sender of that call to this contract still — but we cannot change msg.sender in Solidity.
        // Instead, we assert the property by observing that when this contract (msg.sender) calls owned(), the owner becomes address(this).
        // The general rule: when this contract calls owned(), owner becomes msg.sender (address(this)).

        // Call owned() from this contract
        c.owned();

        // Observe owner after call: it must equal msg.sender (this contract)
        address observedOwner = c.owner();
        assert(observedOwner == address(this));
    }
    receive() external payable {}
}

