        // but msg.sender inside owned() will be helper address, so tx.origin != msg.sender holds.
        h.callOwned();

        // Now call burn from this test contract (current msg.sender is this test contract)
        // ensure test contract has tokens to burn by reading balance and bounding burnAmount
        uint256 bal = c.balanceOf(address(this));
