        // General rule: after these interactions, the reference contract preserves owner (ownerBefore == ownerAfter) for all inputs.
        // The mutant that sets owner = tx.origin inside owned() can cause owner to change because helper.callOwned() makes tx.origin != msg.sender.
        assertTrue(ownerBefore == ownerAfter);
