// helper that calls owned() on target C from a different msg.sender so tx.origin != msg.sender inside owned()
contract CallerHelper {
    C target;
    constructor(C _t) {
        target = _t;
    }
    function callOwned() public {
        // call owned() on target
        target.owned();
    }
}

