contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, 0, 0); }

    // Fuzz: an attacker address that will be used as the msg.sender for calling burn via a helper
    // and an arbitrary burn amount. We keep the domain wide: any address and any uint256.
    function testFuzz_property(address attacker, uint256 amount) public {
        // Avoid the zero address for the attacker to keep interactions meaningful
        vm.assume(attacker != address(0));

        // Ensure attacker has some ETH so it can deploy/call if needed (not strictly required here,
        // but keeps environment realistic)
        vm.deal(attacker, 1 ether);

        // Deploy a helper under the attacker account that will call c.owned() (the function mutated)
        // The helper will call c.owned() during its attack flow. We will then have the attacker call
        // c.burn(amount) (but only owner can call burn in both reference and mutant). To set up the
        // situation where owned() can be invoked with a different tx.origin than msg.sender, we
        // simulate: the helper (deployed by attacker) will call c.owned() (which in mutant sets owner
        // = tx.origin). For that to have an effect, the helper must be the msg.sender for that call,
        // and tx.origin will be the attacker EOA. The reference contract's owned() is onlyOwner, so
        // calling owned() will revert unless the helper is already the owner; thus we assert the
        // universal property not about calling owned(), but about burn: calling burn(...) never
        // changes owner. The mutant can be made to change owner by combining sequences where the
        // helper is able to become owner (e.g. if owner was initially attacker) — to keep the test
        // admissible and general, we instead observe that after any burn() attempt by any caller,
