        // Call burn as owner (this contract). Capture success/failure via try/catch per hard rules.
        bool ok;
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.totalSupply();

        // Single assertion: The reference contract guarantees that either the burn call reverted (ok == false)
        // when owner's balance < amt, or if it succeeded (ok == true) then totalSupply decreased by exactly amt.
        // Concretely: ok implies before - after == amt (use underflow-safe check by computing expected when ok)
        if (ok) {
            assertTrue(before - after == amt);
        } else {
            // If call reverted, totalSupply must be unchanged
            assertTrue(before == after);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: owner mints tokens to itself (or uses existing), then burns some amount
    // We take params: target initial holder (must be owner), mintedAmount, burnAmount
    // The test ensures owner is msg.sender of C by using c.owner() and onlyOwner restrictions apply in C.

    // Single public function with all logic
    function run(address target, uint256 mintedAmount, uint256 burnAmount) public {
        // Preconditions: target must be the owner of c so that onlyOwner calls succeed
        address owner = c.owner();
        require(target == owner, "target must be owner");
        // Record balances and total before actions
        uint256 beforeBalance = c.balanceOf(owner);
        uint256 beforeTotal = c.totalSupply();

        // If needed, mint tokens to owner to ensure sufficient balance for burn
        // Only owner can mint; call must be top-level statement
        if (mintedAmount > 0) {
            c.mintToken(owner, mintedAmount);
        }

        // After mint, recompute available balance and ensure burnAmount is <= balance
        uint256 midBalance = c.balanceOf(owner);
        require(midBalance >= burnAmount, "not enough balance to burn");

        // Perform the burn as owner
        // Note: onlyOwner restricts burn to owner; our caller of C is this test contract, which is not owner.
        // To satisfy onlyOwner, we require that address(this) is the owner. Enforce by require.
        require(owner == address(this) || owner == address(c), "this test must be owner to call burn");

        // However we cannot change c.owner() here. To make calls succeed, the only viable route is when owner == address(this).
        // So require that the stored owner equals this contract; otherwise the burn call will revert and test is inconclusive.
        require(owner == address(this), "test contract must be owner of C");

        c.burn(burnAmount);

        // Observe after state
        uint256 afterBalance = c.balanceOf(owner);
        uint256 afterTotal = c.totalSupply();

        // The invariant that distinguishes P from M: owner's balance decreased by exactly burnAmount
        // (i.e., beforeBalance + mintedAmount - burnAmount == afterBalance)
        // Use values observed: midBalance is beforeBalance + mintedAmount
        assert(afterBalance == midBalance - burnAmount);
    }

    // Fallback and receive to allow this contract to be owner if necessary
    receive() external payable {}
}

